// One fixed bundled photograph; callers supply validated frozen descriptors and crops.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function lensPhotoFigure(p,c,activeControls=''){const z=c.zoom;return `<figure class="lens-photograph" data-lens-photo-figure><div class="lens-photo-window" style="aspect-ratio:3264 / 1840"><img data-lens-photo-image src="assets/lens-bench/onion-epidermis.jpg" loading="lazy" width="3264" height="1840" alt="${esc(p.alt)}" style="width:${z*100}%;height:${z*100}%;left:${(0.5-c.x*z)*100}%;top:${(0.5-c.y*z)*100}%"><p class="lens-photo-fallback" hidden>The photograph could not be loaded. Its source description and credit are below.</p></div>${activeControls}<figcaption><strong>${esc(p.title)}</strong><p>${esc(p.caption)}</p><p>${esc(p.captureLabel)} · Digital enlargement: ${z===1?'Whole photo':`${z} times`}</p><p>Photographer’s title: ${esc(p.sourceTitle)}</p><p>${esc(p.credit)} ${esc(p.license)}</p><p>${esc(p.notice)}</p></figcaption></figure>`;}
